"use strict";const mobileNavigation=document.querySelector(".mobile-nav");mobileNavigation&&mobileNavigation.addEventListener("click",e=>{e.target instanceof Element&&e.target.closest("a")&&mobileNavigation.removeAttribute("open")});const currentYear=document.querySelector("[data-current-year]");if(currentYear){const e=String((new Date).getFullYear());currentYear.dateTime=e,currentYear.textContent=e}
